import corpus from './queryex-lexer-corpus.json';
import { tmQxLex, ɵtmQxPaths, type TmQxToken } from './tm-qx-lex';

// The client's lexer against the engine's: the corpus the engine writes is
// the authority (regenerated by the command in its `regenerate` member),
// and the vectors below restate spec 0008 §4's rules one by one, so a
// failure names the rule as well as the text.

/** A token as the corpus spells it: the call mark only on a call's name. */
function plain(token: TmQxToken): Record<string, unknown> {
  return { kind: token.kind, start: token.start, length: token.length, text: token.text, ...(token.call && { call: true }) };
}

/** The kinds and texts of a text's tokens, for the vectors. */
function kinds(text: string): string[] {
  return tmQxLex(text).tokens.map((token) => `${token.kind}:${token.text}`);
}

/** The problems' codes of a text, with their spans. */
function problems(text: string): string[] {
  return tmQxLex(text).diagnostics.map((diagnostic) => `${diagnostic.code}@${diagnostic.start}+${diagnostic.length}`);
}

describe('tmQxLex', () => {
  describe('the engine corpus', () => {
    it.each(corpus.cases.map((entry) => [JSON.stringify(entry.text), entry] as const))('reads %s as the engine does', (_, entry) => {
      const lexed = tmQxLex(entry.text);
      expect(lexed.tokens.map(plain)).toEqual(entry.tokens);
      expect(lexed.diagnostics).toEqual(entry.diagnostics);
    });

    it('covers every token kind and every lexical problem code', () => {
      const seen = new Set(corpus.cases.flatMap((entry) => entry.tokens.map((token) => token.kind)));
      expect([...seen].sort()).toEqual(['error', 'identifier', 'keyword', 'number', 'parameter', 'punctuator', 'string']);
      const codes = new Set(corpus.cases.flatMap((entry) => entry.diagnostics.map((diagnostic) => diagnostic.code)));
      expect([...codes].sort()).toEqual(['QX1001', 'QX1002', 'QX1003', 'QX1004', 'QX1005']);
    });
  });

  describe('identifiers and keywords', () => {
    it('reads letters, digits and underscores, starting with a letter or an underscore', () => {
      expect(kinds('_x1 Name2 a1.b2')).toEqual(['identifier:_x1', 'identifier:Name2', 'identifier:a1', 'punctuator:.', 'identifier:b2']);
    });

    it('reads a keyword in any ASCII case, and a longer word as a name', () => {
      expect(kinds('AND nOt android')).toEqual(['keyword:AND', 'keyword:nOt', 'identifier:android']);
    });

    it('never folds a non-ASCII letter into a keyword', () => {
      const dotless = String.fromCharCode(0x131);
      expect(kinds(`${dotless}n`)).toEqual([`identifier:${dotless}n`]);
    });

    it('reads a letter beyond the basic plane as one, two code units long', () => {
      const script = String.fromCodePoint(0x1d4b3);
      expect(tmQxLex(`${script}y`).tokens).toEqual([{ kind: 'identifier', start: 0, length: 3, text: `${script}y` }]);
    });

    it('reads a bracketed name without its brackets, a keyword included', () => {
      expect(kinds('[not].[a b]')).toEqual(['identifier:not', 'punctuator:.', 'identifier:a b']);
    });

    it('reports an empty bracketed name and an unterminated one', () => {
      expect(problems('[]')).toEqual(['QX1005@0+2']);
      expect(problems('x [abc')).toEqual(['QX1002@2+4']);
    });

    it('marks a name followed by an opening parenthesis as a call, across white space', () => {
      const tokens = tmQxLex('f (x) g').tokens;
      expect(tokens[0]).toEqual({ kind: 'identifier', start: 0, length: 1, text: 'f', call: true });
      expect(tokens.at(-1)?.call).toBeUndefined();
    });
  });

  describe('numbers', () => {
    it('reads digits with an optional fraction, as written', () => {
      expect(kinds('0 007 3.14 0.500')).toEqual(['number:0', 'number:007', 'number:3.14', 'number:0.500']);
    });

    it('refuses an exponent, hexadecimal, a separator and a bare point as one malformed run', () => {
      expect(problems('1e3')).toEqual(['QX1003@0+3']);
      expect(problems('0x0A')).toEqual(['QX1003@0+4']);
      expect(problems('1_000')).toEqual(['QX1003@0+5']);
      expect(problems('5.')).toEqual(['QX1003@0+2']);
      expect(problems('.5')).toEqual(['QX1003@0+2']);
    });

    it('refuses more than 38 significant digits, leading zeros aside', () => {
      expect(problems('1'.repeat(38))).toEqual([]);
      expect(problems(`000${'1'.repeat(38)}`)).toEqual([]);
      expect(problems('1'.repeat(39))).toEqual(['QX1004@0+39']);
    });

    it('reads digits of another script as unexpected characters', () => {
      const arabic = String.fromCharCode(0x661, 0x662);
      expect(problems(arabic)).toEqual(['QX1005@0+1', 'QX1005@1+1']);
    });
  });

  describe('strings', () => {
    it('collapses a doubled quote and keeps every other character', () => {
      expect(tmQxLex("'It''s a\\b'").tokens).toEqual([{ kind: 'string', start: 0, length: 11, text: "It's a\\b" }]);
    });

    it('reports an unterminated string to the end of the text', () => {
      expect(problems("x = 'abc")).toEqual(['QX1001@4+4']);
      expect(tmQxLex("x = 'abc").tokens.at(-1)).toEqual({ kind: 'error', start: 4, length: 4, text: "'abc" });
    });
  });

  describe('parameters', () => {
    it('reads a parameter with its marker in its span, and its name without it', () => {
      expect(tmQxLex('@From').tokens).toEqual([{ kind: 'parameter', start: 0, length: 5, text: 'From' }]);
      expect(tmQxLex('@[order]').tokens).toEqual([{ kind: 'parameter', start: 0, length: 8, text: 'order' }]);
    });

    it('reports a marker with no name', () => {
      expect(problems('@ x')).toEqual(['QX1005@0+1']);
      expect(problems('@1')).toEqual(['QX1005@0+1']);
    });
  });

  describe('punctuators and white space', () => {
    it('reads the longest operator', () => {
      expect(kinds('a<=b>=c!=d||e')).toEqual([
        'identifier:a',
        'punctuator:<=',
        'identifier:b',
        'punctuator:>=',
        'identifier:c',
        'punctuator:!=',
        'identifier:d',
        'punctuator:||',
        'identifier:e',
      ]);
    });

    it('reports a character that is no token, and goes on after it', () => {
      expect(kinds('a # b')).toEqual(['identifier:a', 'error:#', 'identifier:b']);
      expect(problems('a # b')).toEqual(['QX1005@2+1']);
    });

    it('skips the engine white space and reads the byte-order mark as a character', () => {
      const nbsp = String.fromCharCode(0xa0);
      const nel = String.fromCharCode(0x85);
      const bom = String.fromCharCode(0xfeff);
      expect(kinds(`a${nbsp}b${nel}c`)).toEqual(['identifier:a', 'identifier:b', 'identifier:c']);
      expect(problems(`a${bom}b`)).toEqual(['QX1005@1+1']);
    });
  });
});

describe('ɵtmQxPaths', () => {
  it('reads each path once, the names its points join included, and no function name', () => {
    expect(ɵtmQxPaths("Manager.CreatedAt * 1 + coalesce(Parent.Code, 'x') + Code")).toEqual(['Manager.CreatedAt', 'Parent.Code', 'Code']);
  });

  it('reads no keyword, parameter or literal as a path', () => {
    expect(ɵtmQxPaths("IsActive = true and @From < 'a.b' and Amount is not null")).toEqual(['IsActive', 'Amount']);
  });
});
